/* menu.js - SOL 7 : cinematic main-menu scene (GPU shader Mars, 2 moons, stars, film look) + pause menu.
   Classic script. The game itself (launch.js) is imported in the background AFTER the menu is already animating,
   START unlocks when the game reports window.__gameReady. */
/* the game releases the mouse on purpose (e.g. when the Mars scene starts): remember when, so that is not mistaken for the player pressing Esc */
(function(){const o=document.exitPointerLock;if(o&&!o.__sol){const f=function(){window.__plExit=performance.now();return o.apply(document,arguments)};f.__sol=1;document.exitPointerLock=f}})();
/* ===== SolMusic: one shared procedural music + ambience bed for loading / menu / pad / launch / space / entry / landing (no audio files).
   window.SolMusic.mode('sad'|'loading'|'menu'|'prelaunch'|'launch'|'space'|'entry'|'landing'|'aftermath'|'off')   .duck(0..1) for pause. ===== */
/* ===== SolSettings: MUSIC volume / SOUNDS volume / RENDERING quality (UI lives in the main + pause menu below). Saved in localStorage.
   Audio: every AudioContext the game creates (menu, launch, mars, base) is wrapped so ac.destination is the SOUNDS bus;
          SolMusic's bed is routed to the separate MUSIC bus (ac.__mus). Rendering: launch.js publishes window.__gfx. ===== */
window.SolSettings=(function(){
 const KEY='sol7.settings',S={music:70,sound:70,quality:3,gamma:90},ctxs=[],gain=v=>v/70;
 try{Object.assign(S,JSON.parse(localStorage.getItem(KEY)||'{}'))}catch(e){}
 const AC0=window.AudioContext||window.webkitAudioContext;
 if(AC0&&!AC0.__sol){const dg=Object.getOwnPropertyDescriptor(BaseAudioContext.prototype,'destination').get;
  class AC1 extends AC0{constructor(...a){super(...a);const real=dg.call(this),sg=this.createGain(),mg=this.createGain();sg.gain.value=gain(S.sound);mg.gain.value=gain(S.music);sg.connect(real);mg.connect(real);
   this.__sfx=sg;this.__mus=mg;Object.defineProperty(this,'destination',{value:sg,configurable:true});ctxs.push(this)}}
  AC1.__sol=1;window.AudioContext=AC1}
 const Q=[{n:'LOW',r:.5,sh:512},{n:'MEDIUM',r:.75,sh:1024},{n:'HIGH',r:0,sh:2048},{n:'ULTRA',r:-1,sh:4096}];
 function applyAudio(){for(const c of ctxs){try{c.__sfx.gain.setTargetAtTime(gain(S.sound),c.currentTime,.04);c.__mus.gain.setTargetAtTime(gain(S.music),c.currentTime,.04)}catch(e){}}}
 function applyRender(){const G=window.__gfx;if(!G||!G.renderer)return;const q=Q[S.quality-1]||Q[2],d=window.devicePixelRatio||1,pr=q.r>0?q.r:q.r===0?Math.min(d,1.75):Math.min(d*1.25,2.25);
  if(Math.abs(G.renderer.getPixelRatio()-pr)>.001)G.renderer.setPixelRatio(pr);
  for(const L of G.lights()){if(!L||!L.shadow)continue;if(L.shadow.mapSize.x!==q.sh){L.shadow.mapSize.set(q.sh,q.sh);if(L.shadow.map){L.shadow.map.dispose();L.shadow.map=null}G.renderer.shadowMap.needsUpdate=true}}}
 /* GAMMA: real gamma curve (SVG feComponentTransfer) on the 3D canvas only - HUD and menus are not affected. default 90 (0.90); 100 = off; higher = brighter shadows */
 let gf=null,gApplied=null;
 function applyGamma(){const G=window.__gfx,cv=G&&G.renderer&&G.renderer.domElement;if(!cv)return;const g=Math.max(.5,Math.min(1.8,(S.gamma||90)/100)),want=g===1?'':'url(#sol-gamma)';if(gApplied===g&&cv.style.filter===want)return;gApplied=g;
  if(!gf){const ns='http://www.w3.org/2000/svg',s=document.createElementNS(ns,'svg');s.setAttribute('width','0');s.setAttribute('height','0');s.style.cssText='position:absolute;pointer-events:none';
   s.innerHTML='<filter id="sol-gamma" color-interpolation-filters="sRGB"><feComponentTransfer><feFuncR type="gamma" amplitude="1" exponent="1" offset="0"/><feFuncG type="gamma" amplitude="1" exponent="1" offset="0"/><feFuncB type="gamma" amplitude="1" exponent="1" offset="0"/></feComponentTransfer></filter>';document.body.appendChild(s);gf=[...s.querySelectorAll('feFuncR,feFuncG,feFuncB')]}
  for(const f of gf)f.setAttribute('exponent',String(1/g));cv.style.filter=want}
 const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){}};
 setInterval(()=>{applyRender();applyGamma()},1500);          /* picks up the base sun's shadow map once it exists */
 return{S,Q,applyAudio,applyRender,applyGamma,set(k,v){S[k]=v;save();k==='quality'?applyRender():k==='gamma'?applyGamma():applyAudio()}}})();
/* While the menu is open (window.__paused) nothing may grab the mouse: mars.js re-locks the pointer on every mousedown/keydown and launch.js on canvas click,
   which made the cursor vanish when using the pause menu / Settings sliders. */
