 const M={
  loading:{v:.55,w:.02,f:1200,bar:8,n:5,p:0,ch:[[110,164.8,220,261.6],[87.3,130.8,174.6,220],[130.8,196,261.6,329.6],[98,146.8,196,246.9]]},
  menu:{v:.6,w:.03,f:900,bar:10,n:4,p:0,ch:[[55,110,164.8,220,261.6],[43.65,87.3,130.8,174.6,207.7],[65.4,130.8,196,261.6],[49,98,146.8,196,233.1]]},
  prelaunch:{v:.45,w:.05,f:700,bar:14,n:0,p:0,ch:[[55,82.4,110,164.8],[49,73.4,98,146.8]]},
  launch:{v:.6,w:.03,f:1000,bar:5,n:0,p:96,ch:[[55,110,164.8,220],[65.4,130.8,196,261.6],[73.4,146.8,220,293.7],[82.4,164.8,246.9,329.6]]},
  space:{v:.55,w:0,f:1500,bar:12,n:3.5,p:0,ch:[[130.8,196,261.6,392],[110,164.8,220,329.6],[87.3,130.8,174.6,261.6]]},
  entry:{v:.55,w:.08,f:800,bar:6,n:0,p:110,ch:[[55,82.4,116.5,164.8],[58.3,87.3,123.5,174.6]]},
  landing:{v:.5,w:.06,f:900,bar:6,n:0,p:132,ch:[[55,82.4,110,164.8],[49,73.4,98,146.8]]},
  aftermath:{v:.3,w:.06,f:500,bar:12,n:8,p:0,ch:[[55,82.4,110]]},
  sad:{v:.7,w:.015,f:650,bar:11,n:3.2,p:0,ch:[[110,164.8,261.6,329.6],[87.3,130.8,220,261.6],[98,146.8,233.1,293.7],[82.4,123.5,196,246.9]]},   /* SOL 7: slow, minor, lonely */
  off:{v:0,w:0,f:600,bar:8,n:0,p:0,ch:[[55]]}};
 function init(){if(ac)return;try{ac=new AudioContext();mst=ac.createGain();mst.gain.value=0;mst.connect(ac.__mus||ac.destination);
  fb=ac.createDelay(1);fb.delayTime.value=.46;const fg=ac.createGain(),fl=ac.createBiquadFilter();fg.gain.value=.45;fl.type='lowpass';fl.frequency.value=1500;fb.connect(fl);fl.connect(fg);fg.connect(fb);fl.connect(mst);
  padF=ac.createBiquadFilter();padF.type='lowpass';padF.frequency.value=1000;padF.connect(mst);padF.connect(fb);
  const b=ac.createBuffer(1,ac.sampleRate*2,ac.sampleRate),d=b.getChannelData(0);let l=0;for(let i=0;i<d.length;i++){l=(l+(Math.random()*2-1)*.05)*.97;d[i]=l*5}
  noise=ac.createBufferSource();noise.buffer=b;noise.loop=true;windF=ac.createBiquadFilter();windF.type='bandpass';windF.frequency.value=400;windF.Q.value=.5;
  const gu=ac.createGain(),lf=ac.createOscillator(),lg=ac.createGain();gu.gain.value=.6;lf.frequency.value=.1;lg.gain.value=.4;lf.connect(lg);lg.connect(gu.gain);lf.start();
  windG=ac.createGain();windG.gain.value=0;noise.connect(windF);windF.connect(gu);gu.connect(windG);windG.connect(mst);noise.start();
  initSfx();setInterval(tick,200);apply(true)}catch(e){ac=null}}
 function apply(now){if(!ac)return;const m=M[cur],t=ac.currentTime,k=now?.05:1.8;mst.gain.setTargetAtTime(m.v*.5*duck,t,k);padF.frequency.setTargetAtTime(m.f,t,1);windG.gain.setTargetAtTime(m.w,t,k)}
 function note(f,v,len,type,dest){const t=ac.currentTime,o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(v,t+len*.4);g.gain.exponentialRampToValueAtTime(.0005,t+len);o.connect(g);g.connect(dest);o.start(t);o.stop(t+len+.1)}
 function tick(){if(!ac)return;if(ac.state==='suspended')ac.resume();const m=M[cur],t=ac.currentTime;if(m.v<=0)return;
  if(t>=nc){const ch=m.ch[(beat++)%m.ch.length],len=m.bar*1.35;for(const f of ch){note(f,.05,len,'sine',padF);note(f*1.004,.025,len,'triangle',padF)}nc=t+m.bar}
  if(m.n&&t>=nn){const ch=m.ch[(beat)%m.ch.length],f=ch[(Math.random()*ch.length)|0]*(Math.random()<.5?4:2);note(f,.035,3.2,'sine',padF);nn=t+m.n*(.7+Math.random()*.6)}
  if(m.p){while(np<t+.25){if(np>=t-.05){const s=(Math.round((np*m.p/60))%2)?.6:1;thump(np,.5*s)}np+=60/m.p}}else np=t}
 function thump(at,v){const o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.setValueAtTime(70,at);o.frequency.exponentialRampToValueAtTime(38,at+.18);g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(v,at+.01);g.gain.exponentialRampToValueAtTime(.001,at+.3);o.connect(g);g.connect(mst);o.start(at);o.stop(at+.32)}

