 const el=document.createElement('div');el.id='gm';
 el.innerHTML=`<canvas id="gm-bg"></canvas>
 <div class="box"><h1>SOL 7</h1><div class="sub" id="gm-sub">Seven days. No rescue.</div>
 <div class="main"><button id="gm-cn" style="display:none" disabled>CONTINUE</button><button id="gm-go" disabled>LOADING…</button><button id="gm-ct">CONTROLS</button><button id="gm-st">SETTINGS</button><button id="gm-rs" style="display:none">RESTART MISSION</button><button id="gm-q">QUIT</button></div>
 <div class="pan"><b>W A S D</b> move<br><b>MOUSE</b> look (click game to capture)<br><b>SHIFT</b> sprint<br><b>SPACE</b> jump / RCS<br><b>E</b> interact (ice, crucible, crafting table, airlock)<br><b>LEFT-CLICK</b> swing hammer<br><b>Q</b> use item &nbsp; <b>F</b> deploy crucible / table<br><b>TAB / B</b> backpack &nbsp; <b>1-4 / WHEEL</b> hotbar<br><b>M</b> NASA facts about Phobos &amp; Deimos (night)<br><b>P</b> pause menu &nbsp; <b>R</b> retry (Shift+R inside the base)<br><button id="gm-bk">BACK</button></div>
 <div class="sp"><div class="st">SETTINGS</div>
  <div class="row"><b>MUSIC</b><input type="range" id="st-m" min="0" max="100" step="1"><i id="st-mv"></i></div>
  <div class="row"><b>SOUNDS</b><input type="range" id="st-s" min="0" max="100" step="1"><i id="st-sv"></i></div>
  <div class="row"><b>GAMMA</b><input type="range" id="st-g" min="60" max="160" step="5"><i id="st-gv"></i></div>
  <div class="row"><b>RENDERING</b><input type="range" id="st-q" min="1" max="4" step="1"><i id="st-qv"></i></div>
  <div class="sd" id="st-qd"></div><button id="gm-sb">BACK</button></div></div>
 <div class="hint" id="gm-hint"></div>
 <div class="cf"><div class="cfb"><div class="cft">START A NEW MISSION?</div><div class="cfm">Are you sure? Starting a new mission will overwrite your saved game.</div><button id="gm-cy">YES, OVERWRITE MY SAVE</button><button id="gm-cc">CANCEL</button></div></div>`;
